ALTER PROCEDURE [dbo].[usp_MergeVarResults]
    @Records [dbo].[VarResultsType] READONLY,
    @FileLogId BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Changed INT = 0;

    MERGE [dbo].[VarResults] AS t
    USING @Records AS s
       ON t.[VarDate] = s.[VarDate]
     AND t.[VarBucket] = s.[VarBucket]
     AND t.[LegalEntity] = s.[LegalEntity]
     AND t.[ConfidenceLevelId] = s.[ConfidenceLevelId]
     AND t.[HoldingPeriod] = s.[HoldingPeriod]
     AND t.[TradeBook] = s.[TradeBook]
     AND t.[TradeMonth] = s.[TradeMonth]
     AND t.[ProductSpec] = s.[ProductSpec]
    WHEN MATCHED AND EXISTS (
             -- EXCEPT treats NULL as equal to NULL, so this yields a row only when the
             -- values genuinely differ and ModifiedAtUtc tracks real change. A plain
             -- "t.col <> s.col OR ..." chain is UNKNOWN wherever either side is NULL,
             -- which silently stops detecting changes into and out of NULL.
             SELECT t.[OriginalModifiedAt], t.[RecordState], t.[Guid], t.[Id], t.[EntityName], t.[ConfidenceLevel], t.[ProductGroup], t.[DeltaVar], t.[GammaVar], t.[TotalVar]
             EXCEPT
             SELECT s.[OriginalModifiedAt], s.[RecordState], s.[Guid], s.[Id], s.[EntityName], s.[ConfidenceLevel], s.[ProductGroup], s.[DeltaVar], s.[GammaVar], s.[TotalVar]
         )
    THEN UPDATE SET
             t.[OriginalModifiedAt] = s.[OriginalModifiedAt],
             t.[RecordState] = s.[RecordState],
             t.[Guid] = s.[Guid],
             t.[Id] = s.[Id],
             t.[EntityName] = s.[EntityName],
             t.[ConfidenceLevel] = s.[ConfidenceLevel],
             t.[ProductGroup] = s.[ProductGroup],
             t.[DeltaVar] = s.[DeltaVar],
             t.[GammaVar] = s.[GammaVar],
             t.[TotalVar] = s.[TotalVar],
             t.[FileLogId]     = @FileLogId,
             t.[ModifiedAtUtc] = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([OriginalModifiedAt], [RecordState], [Guid], [Id], [EntityName], [VarDate], [VarBucket], [LegalEntity], [ConfidenceLevelId], [ConfidenceLevel], [HoldingPeriod], [TradeBook], [TradeMonth], [ProductGroup], [ProductSpec], [DeltaVar], [GammaVar], [TotalVar], [FileLogId])
        VALUES (s.[OriginalModifiedAt], s.[RecordState], s.[Guid], s.[Id], s.[EntityName], s.[VarDate], s.[VarBucket], s.[LegalEntity], s.[ConfidenceLevelId], s.[ConfidenceLevel], s.[HoldingPeriod], s.[TradeBook], s.[TradeMonth], s.[ProductGroup], s.[ProductSpec], s.[DeltaVar], s.[GammaVar], s.[TotalVar], @FileLogId);

    SET @Changed = @@ROWCOUNT;

    SELECT @Changed;
END
GO

