ALTER PROCEDURE [dbo].[usp_MergeVolatilities]
    @Records [dbo].[VolatilitiesType] READONLY,
    @FileLogId BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Changed INT = 0;

    MERGE [dbo].[Volatilities] AS t
    USING @Records AS s
       ON t.[SystemDate] = s.[SystemDate]
     AND t.[ProductSpec] = s.[ProductSpec]
     AND t.[InstrumentType] = s.[InstrumentType]
     AND t.[StartTradeMonth] = s.[StartTradeMonth]
     AND t.[EndTradeMonth] = s.[EndTradeMonth]
     AND t.[PutCallFlag] = s.[PutCallFlag]
     AND t.[StrikeType] = s.[StrikeType]
     AND t.[StrikePrice] = s.[StrikePrice]
    WHEN MATCHED AND EXISTS (
             -- EXCEPT treats NULL as equal to NULL, so this yields a row only when the
             -- values genuinely differ and ModifiedAtUtc tracks real change. A plain
             -- "t.col <> s.col OR ..." chain is UNKNOWN wherever either side is NULL,
             -- which silently stops detecting changes into and out of NULL.
             SELECT t.[CreatedAt], t.[ModifiedAt], t.[CreatedByUser], t.[ModifiedByUser], t.[Volatility], t.[AtmFlag], t.[UpdatedFlag]
             EXCEPT
             SELECT s.[CreatedAt], s.[ModifiedAt], s.[CreatedByUser], s.[ModifiedByUser], s.[Volatility], s.[AtmFlag], s.[UpdatedFlag]
         )
    THEN UPDATE SET
             t.[CreatedAt] = s.[CreatedAt],
             t.[ModifiedAt] = s.[ModifiedAt],
             t.[CreatedByUser] = s.[CreatedByUser],
             t.[ModifiedByUser] = s.[ModifiedByUser],
             t.[Volatility] = s.[Volatility],
             t.[AtmFlag] = s.[AtmFlag],
             t.[UpdatedFlag] = s.[UpdatedFlag],
             t.[FileLogId]     = @FileLogId,
             t.[ModifiedAtUtc] = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([CreatedAt], [ModifiedAt], [CreatedByUser], [ModifiedByUser], [SystemDate], [ProductSpec], [InstrumentType], [StartTradeMonth], [EndTradeMonth], [PutCallFlag], [StrikeType], [StrikePrice], [Volatility], [AtmFlag], [UpdatedFlag], [FileLogId])
        VALUES (s.[CreatedAt], s.[ModifiedAt], s.[CreatedByUser], s.[ModifiedByUser], s.[SystemDate], s.[ProductSpec], s.[InstrumentType], s.[StartTradeMonth], s.[EndTradeMonth], s.[PutCallFlag], s.[StrikeType], s.[StrikePrice], s.[Volatility], s.[AtmFlag], s.[UpdatedFlag], @FileLogId);

    SET @Changed = @@ROWCOUNT;

    SELECT @Changed;
END
GO

-- ------------------------------------------------------------------------------------
-- usp_GetPositionDetailsWatermark
--
-- PositionDetails has NO date parameter, so the loader cannot ask for one day. It instead
-- pages a trade month newest-first (SortFields=-systemDate) and stops at the newest
-- date already stored. That watermark is read from the table itself rather than a
-- separate state table, so it is self-healing: delete rows and they are re-fetched.
-- ------------------------------------------------------------------------------------
IF OBJECT_ID(N'[dbo].[usp_GetPositionDetailsWatermark]', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE [dbo].[usp_GetPositionDetailsWatermark] AS BEGIN SET NOCOUNT ON; END');
GO

ALTER PROCEDURE [dbo].[usp_GetPositionDetailsWatermark]
    @TradeMonth VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT MAX([SystemDate])
    FROM [dbo].[PositionDetails]
    WHERE [TradeMonth] = @TradeMonth;
END
GO

